mapper.select:
SELECT dor.id, dor.staff_name, dor.staff_badge, dor.staff_sex, nvl( t3.ALIAS_NAME, t3.ROOM_NAME ) room_name, dor.bed_number, dor.TYPE, dor.room_id, dor.opt_user, dor.dormitory_type_name, dor.time, dor.create_time, sta.comp_name, sta.dep_name, sta.job_name, dor.in_time, dor.park_name, dor.dormitory_name, dor.comp_name AS dor_comp_name, dor.dep_name AS dor_dep_name, dor.job_name AS dor_job_name, sta.lea_type, sta.status, sta.jche_name, dor.in_opt_user, dor.in_create_time FROM smt_dormitory_staff_history dor LEFT JOIN smt_staff sta ON dor.staff_id = sta.id LEFT JOIN smt_dormitory_room t3 ON dor.room_id = t3.id where dor.type!=0
and dor.type =#{query.type}
and dor.staff_name LIKE CONCAT(CONCAT('%',#{query.staffName}),'%')
and dor.staff_badge LIKE CONCAT(CONCAT('%',#{query.staffBadge}),'%')
and (dor.comp_name LIKE CONCAT(CONCAT('%',#{query.compName}),'%') or sta.comp_name LIKE CONCAT(CONCAT('%',#{query.compName}),'%') )
and sta.sex =#{query.sex }
and dor.park_id =#{query.parkId }
and dor.dormitory_id =#{query.dormitoryId }
and dor.floor_id =#{query.floorId }
and dor.room_id =#{query.roomId }
and sta.jche_id =#{query.jcheId }
and dor.in_time between to_date(#{query.inStartTime},'yyyy-mm-dd hh24:mi:ss') and to_date(#{query.inEndTime},'yyyy-mm-dd hh24:mi:ss')
and dor.time between to_date(#{query.outStartTime},'yyyy-mm-dd hh24:mi:ss') and to_date(#{query.outEndTime},'yyyy-mm-dd hh24:mi:ss')
and dor.PARK_ID in
#{item}
and dor.dormitory_id in
#{item}
ORDER BY dor.create_time DESC

      select count(1) from smt_dormitory_staff_history  dor INNER JOIN
		(
			SELECT STAFF_BADGE,staff_name,MAX(CREATE_TIME) AS "atime"
			FROM SMT_DORMITORY_STAFF_HISTORY


				 park_id =#{query.parkId }



				and dormitory_id =#{query.dormitoryId }


			group by STAFF_BADGE,staff_name

		) B
		ON dor.STAFF_BADGE = B.STAFF_BADGE AND dor.CREATE_TIME = B."atime"
		where dor."TYPE"=0

			and dor.park_id =#{query.parkId }



			and dor.dormitory_id =#{query.dormitoryId }



			and dor.in_time < to_date(#{query.inTime},'yyyy-mm-dd hh24:mi:ss')

select dor.id, dor.staff_name, dor.staff_badge ,dor.staff_sex,dor.room_name,dor.bed_number, dor.type, dor.dormitory_type_name,dor.time,dor.create_time,sta.comp_name,sta.dep_name,sta.job_name,dor.in_time, dor.comp_name as dor_comp_name ,dor.dep_name as dor_dep_name,dor.job_name as dor_job_name, sta.jche_name from smt_dormitory_staff_history dor left join smt_staff sta on dor.staff_id=sta.id INNER JOIN ( SELECT STAFF_BADGE,staff_name,MAX(CREATE_TIME) AS "atime" FROM SMT_DORMITORY_STAFF_HISTORY
park_id =#{query.parkId }
and dormitory_id =#{query.dormitoryId }
group by STAFF_BADGE,staff_name
) B ON dor.STAFF_BADGE = B.STAFF_BADGE AND dor.CREATE_TIME = B."atime" where dor."TYPE"=0
and dor.park_id =#{query.parkId }
and dor.dormitory_id =#{query.dormitoryId }
and dor.staff_name LIKE CONCAT(CONCAT('%',#{query.staffName}),'%')
and dor.staff_badge LIKE CONCAT(CONCAT('%',#{query.staffBadge}),'%')
and dor.room_name LIKE CONCAT(CONCAT('%',#{query.roomName}),'%')
and (dor.comp_name LIKE CONCAT(CONCAT('%',#{query.compName}),'%') or sta.comp_name LIKE CONCAT(CONCAT('%',#{query.compName}),'%') )
and dor.in_time < to_date(#{query.inTime},'yyyy-mm-dd hh24:mi:ss')
and dor.in_time between to_date(#{query.startInTime},'yyyy-mm-dd hh24:mi:ss') and to_date(#{query.endInTime},'yyyy-mm-dd hh24:mi:ss')
ORDER BY dor.room_name

     select count(1) from smt_dormitory_bed a


			and a.park_id =#{query.parkId }



			and a.dormitory_id =#{query.dormitoryId }

SELECT id,staff_id,staff_name,staff_sex,staff_badge,park_id,park_name,dormitory_id,dormitory_name,floor_id, floor_name,room_id,room_name,bed_id,bed_number,dormitory_type_id,dormitory_type_name,type, in_time,time,create_time,df_id,is_staff,job_name,comp_name,dep_name FROM smt_dormitory_staff_history t1 WHERE t1.room_id IN
#{item}
AND t1.type IN (1,2,3,4,5) AND t1.statis_flag <> 0 AND ( (t1.IN_TIME BETWEEN #{startTime} AND #{endTime}) or (t1."TIME" BETWEEN #{startTime} AND #{endTime}) or (t1.IN_TIME <= #{startTime} AND t1."TIME" >= #{endTime}) or (#{startTime} <= t1.IN_TIME AND #{endTime} >= t1."TIME" ) )
